+                    ->o("relaxed")
+                    .o(stringifyMemSyncScope(scope).str())
+                    .o("global")
+                    .v(vec)
+                    .b(bitWidth);
+  store(addr, vec == 1 ? inputs->listGet(0) : inputs).maybePredicate(pred);
+  builder.launch(rewriter, loc, void_ty(rewriter.getContext()),
+                 /*hasSideEffect=*/true);
+}
